mapper.select:
SELECT COUNT(DISTINCT CAST(SALES_ORDER AS UNSIGNED))
FROM BASIL_SBX_PRD.RAW_SYSPRO_INPUT


        CAST(SALES_ORDER AS UNSIGNED) = #{salesOrder}



        AND CUSTOMER_PO_NUMBER = #{poNumber}



        AND CAST(CUSTOMER AS UNSIGNED) = #{customerId}


        AND REQ_SHIP_DATE BETWEEN #{shipFromDate} AND #{shipToDate}



        AND ORDER_DATE BETWEEN #{createFromDate} AND #{createToDate}

SELECT DISTINCT CAST(SALES_ORDER AS UNSIGNED) AS salesOrder, CUSTOMER AS customer, COALESCE(scav.VALUE, 'NONE') AS orderStatus, ORDER_DATE AS orderDate, CUSTOMER_PO_NUMBER AS customerPONumber, MO_DESCRIPTION AS moDescription, SPECIAL_INSTRUCTIONS AS specialInstructions, SALES_PERSON_INITIALS AS salesPersonInitials, SALES_PERSON_NAME AS salesPersonName, CONTACT AS contact, CUSTOMER_NAME AS customerName, SHIP_ADDRESS_3_LOC AS shipAddress3Loc, SHIP_ADDRESS_1 AS shipAddress1, SHIP_ADDRESS_2 AS shipAddress2, SHIP_ADDRESS_3 AS shipAddress3, SHIP_ADDRESS_4 AS shipAddress4, SHIP_POSTAL_CODE AS shipPostalCode, EMAIL AS email, REQ_SHIP_DATE AS reqShipDate FROM BASIL_SBX_PRD.RAW_SYSPRO_INPUT LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scav ON scav.SCV_OID = RAW_SYSPRO_INPUT.ORDER_STATUS
CAST(SALES_ORDER AS UNSIGNED) = #{salesOrder}
AND CUSTOMER_PO_NUMBER = #{poNumber}
AND CAST(CUSTOMER AS UNSIGNED) = #{customerId}
AND REQ_SHIP_DATE BETWEEN #{shipFromDate} AND #{shipToDate}
AND ORDER_DATE BETWEEN #{createFromDate} AND #{createToDate}
ORDER BY ${sortColumns}
LIMIT #{offset,jdbcType=INTEGER},#{count,jdbcType=INTEGER}
